/**
 * 全螢幕按鈕插件
 */

import type { MpvPlugin } from '../../core/types/plugin';
import { ControlPlugin, ControlPluginOptions } from '../base/ControlPlugin';
import { fullscreenIcon, fullscreenExitIcon } from '../../renderer/icons';
import styles from './styles.css?inline';

export interface FullscreenPluginOptions extends ControlPluginOptions {
    position?: 'left' | 'right';
    order?: number;
}

export const FullscreenPlugin: MpvPlugin<FullscreenPluginOptions> = {
    name: 'fullscreen',
    version: '1.0.0',
    styles,

    install(player, options = {}) {
        return new FullscreenManager(player, {
            position: options.position ?? 'right',
            order: options.order ?? 20,
        });
    },
};

export class FullscreenManager extends ControlPlugin<Required<FullscreenPluginOptions>> {
    readonly name = 'fullscreen';

    protected createEl(): HTMLElement {
        const btn = document.createElement('button');
        btn.className = 'vp-btn vp-fullscreen-btn';
        btn.title = '全螢幕 (F)';
        btn.innerHTML = `
            <span class="vp-icon-fullscreen">${fullscreenIcon}</span>
            <span class="vp-icon-exit-fullscreen">${fullscreenExitIcon}</span>
        `;

        this.on(btn, 'click', (e) => {
            e.stopPropagation();
            this.toggleFullscreen();
        });

        this.on(document, 'fullscreenchange', () => this.updateState());

        return btn;
    }

    private toggleFullscreen(): void {
        if (!document.fullscreenElement) {
            this.player.requestFullscreen();
        } else {
            document.exitFullscreen();
        }
    }

    private updateState(): void {
        const isFullscreen = !!document.fullscreenElement;
        this.player.classList.toggle('fullscreen', isFullscreen);
    }
}

